package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1024*1024*1024)

	var s string
	counter := 0

	for scanner.Scan() {
		line := scanner.Text()

		if counter == 0 {
			s = line
		} else {
			t := line
			answer := "YES"

			if len(t) > len(s) {
				answer = "NO"
			} else {
				for i, j := len(t)-1, 0; i >= 0; i, j = i-1, j+1 {
					if t[i] != s[j] {
						answer = "NO"
						break
					}
				}
			}

			fmt.Println(answer)
		}

		counter++
	}
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"unicode/utf16"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1024*1024*100)

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	counter := 0
	var s []uint16

	for scanner.Scan() {
		line := scanner.Text()

		if counter == 0 {
			s = utf16.Encode([]rune(line))
		} else {
			t := utf16.Encode([]rune(line))
			answer := "YES"
			j := 0

			for i := len(t) - 1; i >= 0; i-- {
				if j >= len(s) || t[i] != s[j] {
					answer = "NO"
					break
				}
				j++
			}

			fmt.Fprintln(writer, answer)
		}

		counter++
	}
}

